<script setup>
import { computed, onMounted, ref } from 'vue'
import { apiGet, apiRequest } from '../services/api.js'
import { useAuthStore, roles, managementLevels } from '../stores/auth.js'
import { today, label } from '../utils.js'
import FormPanel from '../components/FormPanel.vue'
const auth = useAuthStore(), companies = ref([]), company = ref(''), data = ref(null), slots = ref([]), error = ref(''), notice = ref(''), invite = ref(''), busy = ref(false), section = ref('unit'), formKey = ref(0)
const platform = computed(() => auth.user.role === 'admin' && auth.user.management_level === 'platform')
const formInitial = ref({}), contractEditing = ref(null)
function editContract(c) { section.value = 'contract'; contractEditing.value = c; formInitial.value = { ...c, allow_in_person: !!Number(c.allow_in_person), allow_telehealth: !!Number(c.allow_telehealth), allow_dependents: !!Number(c.allow_dependents) }; formKey.value++; window.scrollTo({ top: 0, behavior: 'smooth' }) }
const careManagement = computed(() => platform.value || ['doctor', 'nurse'].includes(auth.user.role) && auth.user.management_level === 'coordination')
const entries = (rows, text = 'name') => (rows || []).map(r => ({ value: Number(r.id), label: `${r[text]} (#${r.id})` }))
const field = (name, title, more = {}) => ({ name, label: title, ...more })
const sections = computed(() => [
  ...(platform.value ? [{ id: 'company', title: 'Nova indústria' }, { id: 'account', title: 'Usuários e níveis' }, { id: 'team', title: 'Criar equipe' }, { id: 'member', title: 'Vincular profissional' }] : []),
  { id: 'unit', title: 'Unidade industrial' }, { id: 'contract', title: 'Contrato APS' }, { id: 'invite', title: 'Convite de cadastro' }, { id: 'minor', title: 'Dependente menor' },
  ...(careManagement.value ? [{ id: 'location', title: 'Local de atendimento' }, { id: 'slot', title: 'Disponibilidade' }, { id: 'assignment', title: 'Vínculo assistencial' }] : []),
])
const forms = computed(() => {
  const coordinates = [field('latitude', 'Latitude (opcional)', { type: 'number', optional: true }), field('longitude', 'Longitude (opcional)', { type: 'number', optional: true })]
  const address = [field('name', 'Nome', { max: 150 }), field('address', 'Endereço', { max: 300 }), field('postal_code', 'CEP', { max: 9 }), ...coordinates]
  return {
    company: [field('name', 'Nome da indústria', { max: 150 })],
    unit: address,
    location: [...address, field('kind', 'Tipo de local', { options: [{ value: 'sesi', label: 'Unidade SESI' }, { value: 'industry', label: 'Na indústria' }] })],
    contract: [field('name', 'Identificação do contrato'), field('start_date', 'Início da vigência', { type: 'date', default: today() }), field('end_date', 'Fim da vigência', { type: 'date' }), field('status', 'Situação', { options: [{ value: 'active', label: 'Ativo' }, { value: 'paused', label: 'Pausado' }], default: 'active' }), field('allow_in_person', 'Inclui presencial', { type: 'checkbox', default: true }), field('allow_telehealth', 'Inclui teleconsulta', { type: 'checkbox', default: true }), field('allow_dependents', 'Inclui dependentes', { type: 'checkbox', default: true })],
    account: [field('name', 'Nome do profissional'), field('email', 'E-mail', { type: 'email' }), field('password', 'Senha inicial (12–72 bytes)', { type: 'password', max: 72 }), field('role', 'Perfil profissional', { options: ['doctor', 'nurse', 'navigator', 'manager'].map(value => ({ value, label: roles[value] })) }), field('management_level', 'Nível de gestão independente do perfil', { options: ['none', 'coordination', 'company'].map(value => ({ value, label: managementLevels[value] })), default: 'none', help: 'Coordenação: médico/enfermeiro. Gestão empresarial: gestor.' })],
    team: [field('name', 'Nome da equipe APS')],
    assignment: [field('patient_id', 'Beneficiário', { options: (data.value?.beneficiaries || []).map(b => ({ value: Number(b.patient_id), label: b.name })) }), field('team_id', 'Equipe APS', { options: entries(data.value?.teams) }), field('active', 'Vínculo ativo (desmarcar para revogar)', { type: 'checkbox', default: true }), field('authorization_verified', 'Verifiquei a autorização assistencial para esta equipe', { type: 'checkbox', wide: true })],
    member: [field('team_id', 'Equipe', { options: entries(data.value?.teams) }), field('user_id', 'Profissional', { options: entries(data.value?.professionals) })],
    invite: [field('email', 'E-mail de quem será cadastrado', { type: 'email' }), field('contract_id', 'Contrato vigente', { options: entries(data.value?.contracts) }), field('industry_unit_id', 'Unidade industrial', { options: entries(data.value?.industry_units) }), field('kind', 'Tipo do beneficiário', { options: [{ value: 'worker', label: 'Trabalhador' }, { value: 'dependent', label: 'Dependente adulto' }] }), field('sponsor_patient_id', 'Titular (somente para dependentes)', { type: 'number', optional: true, help: 'ID do paciente titular, apresentado na lista de beneficiários.' })],
    minor: [field('sponsor_patient_id', 'ID do paciente titular', { type: 'number' }), field('name', 'Nome do dependente menor'), field('birth_date', 'Nascimento', { type: 'date' }), field('authorization_reference', 'Referência da verificação institucional da representação'), field('representation_verified', 'Verifiquei a representação e a autorização conforme o procedimento institucional', { type: 'checkbox', wide: true })],
    slot: [field('professional_id', 'Profissional', { options: entries(data.value?.professionals.filter(p => ['doctor', 'nurse'].includes(p.role))) }), field('team_id', 'Equipe APS', { options: entries(data.value?.teams) }), field('service_unit_id', 'Local de atendimento', { options: entries(data.value?.service_units) }), field('modality', 'Modalidade', { options: [{ value: 'in_person', label: 'Presencial' }, { value: 'telehealth', label: 'Teleconsulta' }] }), field('starts_at', 'Início', { type: 'datetime-local' }), field('ends_at', 'Término', { type: 'datetime-local' })],
  }
})
const suffix = () => '?' + new URLSearchParams({ company_id: company.value })
async function load() { data.value = await apiGet('/management/overview' + suffix()); slots.value = careManagement.value ? await apiGet('/management/slots' + suffix()) : [] }
async function changeCompany() { formInitial.value = {}; contractEditing.value = null; invite.value = ''; error.value = ''; notice.value = ''; data.value = null; busy.value = true; formKey.value++; try { await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function submit(form) {
  busy.value = true; error.value = ''; notice.value = ''; invite.value = ''
  try {
    const endpoints = { company: 'companies', unit: 'industry-units', location: 'service-units', contract: 'contracts', account: 'users', team: 'teams', member: 'team-members', invite: 'invitations', minor: 'represented-dependents', slot: 'slots', assignment: 'care-assignments' }
    const payload = { ...form }
    for (const key of ['starts_at', 'ends_at']) if (payload[key]) payload[key] = payload[key].replace('T', ' ') + (payload[key].length === 16 ? ':00' : '')
    const editing = section.value === 'contract' && contractEditing.value
    const result = await apiRequest('/management/' + endpoints[section.value] + (editing ? '/' + editing.id : '') + suffix(), editing ? 'PUT' : 'POST', { ...payload, ...(editing ? { version: Number(editing.version) } : {}) })
    if (result.registration_path) invite.value = new URL(result.registration_path, window.location.origin).href
    if (section.value === 'company') { companies.value = await apiGet('/management/companies'); company.value = result.id }
    await load(); formKey.value++; formInitial.value = {}; contractEditing.value = null; notice.value = 'Registro salvo. O acesso clínico continua dependendo do vínculo assistencial.'
  } catch (e) { error.value = e.message } finally { busy.value = false }
}
async function validate(b, activate) {
  if (activate && !window.confirm(`Confirma que o contato e o vínculo de ${b.name} foram verificados?`)) return
  busy.value = true; error.value = ''
  try { await apiRequest(`/management/beneficiaries/${b.id}` + suffix(), 'PUT', { status: activate ? 'active' : 'suspended', contact_verified: activate, affiliation_verified: activate }); await load() } catch (e) { error.value = e.message } finally { busy.value = false }
}
async function accountLevel(u, level) { busy.value = true; error.value = ''; try { await apiRequest(`/management/users/${u.id}` + suffix(), 'PUT', { management_level: level, active: !!Number(u.active) }); await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function block(slot) { busy.value = true; error.value = ''; try { await apiRequest(`/management/slots/${slot.id}/block` + suffix(), 'POST', { version: Number(slot.version) }); await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
onMounted(async () => { busy.value = true; try { companies.value = await apiGet('/management/companies'); company.value = companies.value.find(c => Number(c.id) === Number(auth.user.company_id))?.id || companies.value[0]?.id; await load() } catch (e) { error.value = e.message } finally { busy.value = false } })
</script>
<template><p class="eyebrow">SESI · GESTÃO PARA A INDÚSTRIA</p><h1>Contratos, pessoas e acesso ao cuidado</h1><p class="text-secondary">{{ managementLevels[auth.user.management_level] }} · Dados administrativos separados dos prontuários.</p><label for="industry" class="form-label">Indústria contratante</label><select id="industry" v-model="company" class="form-select mb-4" :disabled="busy" @change="changeCompany"><option v-for="c in companies" :key="c.id" :value="c.id">{{ c.name }}</option></select><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p><div v-if="invite" class="alert alert-info"><strong>Convite individual, válido por 48 horas</strong><p class="small">Entregue somente ao destinatário. O sistema não envia mensagens automaticamente.</p><input class="form-control" :value="invite" readonly aria-label="Link de cadastro" @focus="$event.target.select()"></div><p v-if="busy" role="status">Processando…</p><template v-if="data"><div class="row g-4"><aside class="col-lg-3"><nav class="nav nav-pills flex-column gap-1" aria-label="Cadastros de gestão"><button v-for="s in sections" :key="s.id" class="nav-link text-start" :class="{ active: section === s.id }" :disabled="busy" @click="section = s.id; formKey++; formInitial = {}; contractEditing = null">{{ s.title }}</button></nav><RouterLink to="/education-editor" class="d-block mt-4">Conteúdos educativos →</RouterLink><RouterLink to="/campaign-management" class="d-block mt-3">Campanhas e ciclos →</RouterLink></aside><section class="col-lg-9"><div class="card card-body"><h2 class="h4">{{ sections.find(s => s.id === section)?.title }}</h2><FormPanel :key="`${section}-${company}-${formKey}`" :fields="forms[section] || []" :initial="formInitial" :busy="busy" @submit="submit" /></div></section></div>
<section class="card card-body mt-4"><h2 class="h5">Trabalhadores e dependentes · validação administrativa</h2><div class="table-responsive"><table class="table"><thead><tr><th>Paciente</th><th>Vínculo</th><th>Contrato</th><th>Situação</th><th>Ações</th></tr></thead><tbody><tr v-for="b in data.beneficiaries" :key="b.id"><td>{{ b.name }} <small>#{{ b.patient_id }}</small><br><small>{{ b.email }}</small></td><td>{{ b.kind === 'worker' ? 'Trabalhador' : 'Dependente' }}<small v-if="b.sponsor_patient_id"> · titular #{{ b.sponsor_patient_id }}</small></td><td>#{{ b.contract_id }}</td><td>{{ label(b.status) }}</td><td><button class="btn btn-sm btn-outline-success me-2" :disabled="busy || b.status === 'active'" @click="validate(b, true)">Validar vínculo</button><button class="btn btn-sm btn-outline-secondary" :disabled="busy || b.status === 'suspended'" @click="validate(b, false)">Suspender</button></td></tr></tbody></table></div></section>
<section class="card card-body mt-4"><h2 class="h5">Contratos e unidades</h2><p v-for="c in data.contracts" :key="c.id">#{{ c.id }} · {{ c.name }} · {{ c.start_date }} a {{ c.end_date }} · {{ label(c.status) }} · {{ Number(c.allow_in_person) ? 'Presencial' : '' }} {{ Number(c.allow_telehealth) ? 'Teleconsulta' : '' }} {{ Number(c.allow_dependents) ? '· Dependentes incluídos' : '' }} <button class="btn btn-sm btn-outline-secondary ms-2" :disabled="busy" @click="editContract(c)">Editar vigência e cobertura</button></p><p v-for="u in data.industry_units" :key="u.id">#{{ u.id }} · {{ u.name }} · {{ u.address }}</p></section>
<section v-if="platform" class="card card-body mt-4"><h2 class="h5">Profissionais e níveis de gestão</h2><p class="small text-secondary">Coordenação não concede prontuários sem vínculo assistencial.</p><div class="table-responsive"><table class="table"><thead><tr><th>Usuário</th><th>Perfil</th><th>Nível</th><th>Alterar nível</th></tr></thead><tbody><tr v-for="u in data.accounts" :key="u.id"><td>{{ u.name }}</td><td>{{ roles[u.role] }}</td><td>{{ managementLevels[u.management_level] }}</td><td><select v-if="['doctor', 'nurse', 'manager', 'navigator'].includes(u.role)" class="form-select" :aria-label="`Nível de ${u.name}`" :value="u.management_level" :disabled="busy" @change="accountLevel(u, $event.target.value)"><option value="none">Sem gestão</option><option v-if="['doctor', 'nurse'].includes(u.role)" value="coordination">Coordenação APS</option><option v-if="u.role === 'manager'" value="company">Gestão empresarial</option></select></td></tr></tbody></table></div></section>
<section v-if="careManagement" class="card card-body mt-4"><h2 class="h5">Agenda disponibilizada</h2><div class="table-responsive"><table class="table"><thead><tr><th>Profissional</th><th>Horário</th><th>Modalidade</th><th>Situação</th><th>Ação</th></tr></thead><tbody><tr v-for="s in slots" :key="s.id"><td>{{ s.professional_name }}<br>{{ s.unit_name }}</td><td>{{ s.starts_at }} — {{ s.ends_at }}</td><td>{{ s.modality === 'telehealth' ? 'Teleconsulta' : 'Presencial' }}</td><td>{{ label(s.status) }}</td><td><button v-if="s.status === 'available'" class="btn btn-sm btn-outline-secondary" :disabled="busy" @click="block(s)">Bloquear</button></td></tr></tbody></table></div></section></template></template>
